import React from 'react';
import ReadyOrders from './ReadyOrders';
import DigitalClock from './DigitalClock';
import ScrollingBanner from './ScrollingBanner';

const Dashboard = () => {
  return (
    <div className="fullscreen-dashboard dark-theme bg-gray-950">
      {/* Header with Digital Clock */}
      <header className="flex justify-between items-center p-6">
        <div className="text-4xl xl:text-6xl font-bold text-white">
          READY ORDERS
        </div>
        <DigitalClock />
      </header>

      {/* Main Content Area - Token Display */}
      <main className="flex-1 overflow-hidden flex items-center justify-center">
        <ReadyOrders />
      </main>

      {/* Scrolling Banner */}
      <ScrollingBanner />
    </div>
  );
};

export default Dashboard;
